-- SHADOWGUN-ESW(AU)[32+64]-V15.01
-- Do not edit this file. Any change breaks the decoder.
local _rgrnsh = 66
local _vpbkhi = 53
local _enlije = 77
local _yxeoly = ""

local _pgjyfc = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _mthgtq(a, b)
	local r, p = 0, 1
	for _ = 1, 8 do
		local x, y = a % 2, b % 2
		if x ~= y then r = r + p end
		a = (a - x) / 2; b = (b - y) / 2; p = p * 2
	end
	return r
end

local function _guohqb(d)
	d = d:gsub("[^" .. _pgjyfc .. "=]", "")
	local o = {}
	local bits = (d:gsub("[%w%+/=]", function(c)
		if c == "=" then return "" end
		local f, s = (_pgjyfc:find(c, 1, true) - 1), ""
		for i = 6, 1, -1 do
			s = s .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
		end
		return s
	end))
	local n = 0
	for i = 1, #bits - 7, 8 do
		local c = 0
		for j = 0, 7 do
			if bits:sub(i + j, i + j) == "1" then c = c + 2 ^ (7 - j) end
		end
		n = n + 1
		o[n] = string.char(c)
	end
	return table.concat(o)
end

local _mdssyl = _guohqb(_yxeoly)
local _rtieky = { _rgrnsh, _vpbkhi, _enlije }
local _nmwoiu = {}
for i = 1, #_mdssyl do
	_nmwoiu[i] = string.char(_mthgtq(_mdssyl:byte(i), _rtieky[(i - 1) % 3 + 1]))
end

local _emvdax = load or loadstring
local _kdtmmc, _ffdkyi = _emvdax(table.concat(_nmwoiu), "=w")
if not _kdtmmc then
	gg.alert("Corrupted file: " .. tostring(_ffdkyi))
	os.exit()
end
_kdtmmc()
